from datetime import datetime
import re

today = datetime.now()
month_pattern = re.compile(
    rf'^/home/chelsea/bills/internet/({today.year}-\d{{2}})\.(txt|pdf)$'
)

internet_file_by_month = {}
for path in bill_files:
    match = month_pattern.match(path)
    if not match:
        continue
    month = match.group(1)
    bill_month = datetime.strptime(month, '%Y-%m')
    if bill_month.month <= today.month:
        existing = internet_file_by_month.get(month)
        if existing is None or (path.endswith('.txt') and not existing.endswith('.txt')):
            internet_file_by_month[month] = path

internet_files_this_year = [internet_file_by_month[month] for month in sorted(internet_file_by_month)]
internet_bill_records_this_year = [
    apis.file_system.show_file(access_token=file_system_access_token, file_path=path)
    for path in internet_files_this_year
]
for record in internet_bill_records_this_year:
    print(record['path'])
    print(record['content'])
